INSERT INTO mode_super_objet (id, nom, ordre, effet_passif, effet_actif, effets_brut, description, origine, source_ref, remarque) VALUES ('guide/liste-des-effets-mode-super#objet:super-gemme', 'Super gemme', 15, 'Les dégâts de l''élément de la gemme augmente de +10 au lieu de +7.', 'Permet de lancer un sort un cran au dessus de la puissance magique actuelle pour un coût 50% plus chère (sort lvl 5 limité au mono magie) (1 fois/24h)', 'Effet passif = Les dégâts de l''élément de la gemme augmente de +10 au lieu de +7.
Effet actif = Permet de lancer un sort un cran au dessus de la puissance magique actuelle pour un coût 50% plus chère (sort lvl 5 limité au mono magie) (1 fois/24h)', 'Le porteur fusionne avec la gemme temporairement pour exploiter sa pleine puissance. La super gemme sortira légèrement du dos de l''utilisateur. Les attributs physiques vont énormément changer et la chair va être temporairement de la même matière que la gemme à certains endroits.', 'annexes', 'Mode hyper et co › Mode Super › A59:AG62', NULL);
